import { test } from 'node:test';
import assert from 'node:assert/strict';
import create from '../build/host.gen.ts';

test('lifecycle', async () => {
  const h = await create();
  assert.deepEqual(await h.node(), { role: 'follower', term: 0 });
  assert.equal((await h.electionWon()).ok, false);
  assert.equal((await h.quorumLost()).ok, false);
  assert.deepEqual(await h.electionTimeout(), { ok: true });
  assert.deepEqual(await h.node(), { role: 'candidate', term: 1 });
  assert.deepEqual(await h.electionWon(), { ok: true });
  assert.deepEqual(await h.node(), { role: 'leader', term: 1 });
  assert.equal((await h.electionTimeout()).ok, false);
  assert.deepEqual(await h.quorumLost(), { ok: true });
  assert.deepEqual(await h.node(), { role: 'follower', term: 1 });
  assert.equal((await h.newerTermSeen(1)).ok, false);
  assert.equal((await h.newerTermSeen(4)).ok, false);
  assert.equal((await h.newerTermSeen(0)).ok, false);
  assert.deepEqual(await h.newerTermSeen(3), { ok: true });
  assert.deepEqual(await h.node(), { role: 'follower', term: 3 });
  assert.equal((await h.electionTimeout()).ok, false);
  assert.deepEqual(await h.shutdown(), { ok: true });
  assert.deepEqual(await h.node(), { role: 'shutdown', term: 3 });
  for (const r of [await h.shutdown(), await h.electionTimeout(), await h.newerTermSeen(3), await h.quorumLost(), await h.electionWon()])
    assert.equal(r.ok, false);
  assert.deepEqual(await h.node(), { role: 'shutdown', term: 3 });
});

test('fresh and leader sees newer term', async () => {
  const h = await create();
  await h.electionTimeout(); await h.electionWon();
  assert.deepEqual(await h.newerTermSeen(2), { ok: true });
  assert.deepEqual(await h.node(), { role: 'follower', term: 2 });
  assert.deepEqual(await (await create()).node(), { role: 'follower', term: 0 });
});

